import logging
import re
import time
from typing import Union

from ute_ue.config import loggers as ta_ue_logging
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments

import taf.ue.android.data_transfer.icmp.ping_options as ping_options
from taf.ue.android.data_transfer.iperf.data_transfer import DT_MAX_TIME, AndroidUeDtConfigPacker
from taf.ue.android.data_transfer.utils.data_transfer_utils import get_ip_version
from taf.ue.android.data_transfer.utils.ip_addr_selector import IpAddressSelector
from taf.ue.android.exceptions import (
    AllowedPacketLossReached,
    DataTransferException,
    HostNotReachableError,
    NetworkUnreachableError,
    NoIpError,
    UnexpectedCmdResultException,
)
from taf.ue.android.utils.ssh_manager import SshManager
from taf.ue.android.utils.utils import Utils


class AndroidDataTransferIcmp(LteDataTransfer):
    # pylint: disable=protected-access

    def __init__(self, name, dt_definition, configuration, ue_instance, logger_name='ute_ue'):
        """
        Object responsible for managing icmp data transfer for AndroidUe
        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependent configuration provided by UE instance needed for data transfer operations
        :param ue_instance:
        """
        super().__init__(name, dt_definition, configuration, logger_name)

        self.utils = Utils()
        self.ue_instance = ue_instance
        self.dt_config = IcmpDtConfigPacker(self._dt_definition, self._configuration, self.logger).get_config()
        self.is_direction_downlink = self.dt_config['direction'] == "dl"

        self.result = None
        self.is_dt_running = False
        self.success_started = False
        self.ssh_manager = None
        self.downlink_ssh_reader = None
        self.ping_cmd = None

        self.logger.debug(f"{self.name} created with configuration: {self.dt_config}")

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self.logger.debug(f"{self.name} call: starting ping data transfer")
        self.is_dt_running = True
        if self.is_direction_downlink:
            self.ping_ue()
        else:
            self.ping_app_server()
        self.success_started = True
        self.logger.debug(f"{self.name}: ping data transfer successfully started!")

    def ping_ue(self):
        """Ping UE from app server"""
        app_server_ip = self._get_app_server_ip()
        ue_ip = self._get_ip_to_ping_from_app_server()
        self.ping_cmd = self._get_ping_cmd(ip_to_ping=ue_ip)
        ssh = self._create_ssh_manager_and_register_host(self.dt_config['app_server'])
        self.logger.debug(f'{self.name}: triggering ping App Server ({app_server_ip}) --> ({ue_ip}) UE '
                          f'{self.ue_instance.ue_id}.', extra={'ue_id': self.ue_instance.ue_id})
        self.downlink_ssh_reader = ssh.run_cmd_and_get_non_blocking_reader(self.ping_cmd, app_server_ip)

    def ping_app_server(self):
        """Ping app server from UE"""
        ip_to_ping = self._get_ip_to_ping_from_ue()
        self.ping_cmd = self._get_ping_cmd(ip_to_ping=ip_to_ping)
        self.logger.debug(f'{self.name}: triggering ping UE {self.ue_instance.ue_id} --> App Server ({ip_to_ping}).',
                          extra={'ue_id': self.ue_instance.ue_id})
        self.ue_instance.rpc_client.start_data_transfer(
            ue_id=self.ue_instance.ue_id, data_transfer_id=self.name,
            data_transfer_class="AndroidPing", data_transfer_cmd=self.ping_cmd)

    def _get_ip_to_ping_from_app_server(self):
        """Returns ip that App Server will ping: only the UE address in our case is possible"""
        ue_interfaces = self.ue_instance.rpc_client.get_ue_info(ue_id=self.ue_instance.ue_id,
                                                                ue_attributes=['ips'])['ips']
        agent_addresses = IpAddressSelector.select_net_interface_by_attribute_or_take_available(
            network_interfaces_info=ue_interfaces, network_setting=self.dt_config['interface_name'], logger=self.logger)
        try:
            as_ip_version = self.dt_config['app_server']['ip_version']
            self.logger.debug(f"Selecting IPv{as_ip_version} address from UE {self.ue_instance.ue_id} "
                              "for downlink ping data transfer")
            return IpAddressSelector.select_ip_by_version(ip_addresses=agent_addresses, logger=self.logger,
                                                          ip_version=as_ip_version)
        except NoIpError:
            first_available_address = agent_addresses[0]
            self.logger.debug(f"No IPv{self.dt_config['app_server']['ip_version']} found on UE "
                              f"{self.ue_instance.ue_id}. Selecting first available address: {first_available_address}")
            return first_available_address

    def _get_ip_to_ping_from_ue(self):
        """Returns ip that UE will ping: any ping_host_ip if is given or app server ip"""
        if 'address' in self.dt_config and self.dt_config['address'] is not None:
            return self.dt_config['address']
        if 'address' in self.dt_config['app_server']:
            return self._get_icmp_connection_ip()
        raise DataTransferMissingArguments("Please provide IP for ping. Possible entries are:\n"
                                           "- `address` robot keyword argument\n"
                                           "- `address` at data_transfer['ping'] yaml section\n"
                                           "- `address` for app_server")

    def _get_icmp_connection_ip(self):
        bind_ip = self._get_app_server_bind_ip()
        address = self._get_app_server_ip()
        return bind_ip or address

    def _get_app_server_bind_ip(self):
        bind_ip = self.dt_config['app_server'].get('bind_interface_ip')
        if not isinstance(bind_ip, str) or not bind_ip:
            raise ValueError("bind_interface_ip must be a non-empty string and always be specified during DT execution")
        return bind_ip

    def _get_app_server_ip(self):
        address = self.dt_config['app_server'].get('address')
        if not isinstance(address, str) or not address:
            raise ValueError("address must be a non-empty string and always be specified")
        return address

    def _get_ping_cmd(self, ip_to_ping):
        options_to_search = \
            ping_options.PING_OPTIONS_DOWNLINK if self.is_direction_downlink else ping_options.PING_OPTIONS_UPLINK
        ping_arguments = ['ping6' if get_ip_version(ip_to_ping) == 6 else 'ping']
        for option_name, attr_symbol in options_to_search.items():
            if option_name in self.dt_config and self.dt_config[option_name] is not None:
                ping_parameter = f'-{attr_symbol} {self.dt_config[option_name]}'
                ping_arguments.append(ping_parameter)
        ping_arguments.append(ip_to_ping)
        ping_cmd = ' '.join(ping_arguments)
        self.logger.debug(f'{self.name} ping command: {ping_cmd}')
        return ping_cmd

    def await_finish(self):
        """Waits until this data transfer finish"""
        if self.get_definition().is_forever_duration():
            raise DataTransferException("Can not await forever."
                                        f"\nPlease set finite duration for {self.name} data transfer")
        elif not self.is_running() and self.result:
            self.logger.info(f'Ping already finished, output:\n{self.result}')
            return
        self.logger.info(f"Awaiting for ping data transfer to finish {self.dt_config['timeout']} seconds "
                         f"with {self.dt_config['interval']} seconds interval")
        if self.is_direction_downlink:
            self.result = self.utils.get_non_blocking_reader_result(self.downlink_ssh_reader,
                                                                    timeout=int(self.dt_config['timeout']),
                                                                    interval=self.dt_config['interval'])
        else:
            self.result = self.await_ping_app_server_finish()
        self.result = "\n".join(self.result)
        self.logger.debug(f'{self.name} output: {self.result}', extra={'ue_id': self.ue_instance.ue_id})
        self.logger.info(f'Ping finished, output:\n{self.ping_cmd}\n{self.result}')
        self._verify_ping_output(self.result, self.dt_config['allowed_packet_loss'])
        self.is_dt_running = False

    def await_ping_app_server_finish(self):
        """
        Wait for the end of ping until its finished (reader claimed to be finished)
        or the self.ping_parameters['timeout'] exceeded.
        :return:
        """
        end_time = time.time() + float(self.dt_config['timeout'])
        while time.time() <= end_time:
            time_left = int(end_time - time.time())
            self.logger.debug(f"{self.name}: awaiting finish, time left: {time_left}s")
            if not self.is_running():
                took_time = self.dt_config['timeout'] - time_left
                self.logger.debug(f"{self.name}: data transfer finished in {took_time}s")
                break
            time.sleep(self.dt_config['interval'])
        return self.ue_instance.rpc_client.get_data_transfer_output(
            ue_id=self.ue_instance.ue_id, data_transfer_id=self.name, raw_output=True)['raw_output']

    @staticmethod
    def _raise_if_output_is_empty(ping_output):
        if not ping_output or len(ping_output) == 0:
            raise UnexpectedCmdResultException('Ping output is empty!')

    def _raise_if_network_unreachable(self, ping_output, allowed_packet_loss):
        if 'Network is unreachable' in ping_output:
            packet_loss = int(self._husk_value_from_ping_output('packet_loss', ping_output))
            if packet_loss > int(allowed_packet_loss):
                raise NetworkUnreachableError('Network is unreachable! Please check '
                                              f'if UE is attached and if it has correct IP! {ping_output}')
            else:
                self.logger.debug(f'Network is unreachable! Packet loss is {packet_loss}%, what is allowed '
                                  f'(below {allowed_packet_loss}%.')

    def _verify_ping_output(self, ping_output, allowed_packet_loss):
        self._raise_if_output_is_empty(ping_output)
        self._raise_if_network_unreachable(ping_output, allowed_packet_loss)
        self._verify_packet_loss(ping_output, allowed_packet_loss)

    def _verify_packet_loss(self, ping_output, allowed_packet_loss):
        packet_loss = int(self._husk_value_from_ping_output('packet_loss', ping_output))
        if packet_loss == 100:
            raise HostNotReachableError("Packet loss 100%")
        if packet_loss > int(allowed_packet_loss):
            raise AllowedPacketLossReached(f"Allowed packet loss reached: {packet_loss}% > {allowed_packet_loss}%")

    @staticmethod
    def _husk_value_from_ping_output(stats_name, ping_output):
        stats_regex = ping_options.PING_STATS_REGEX[stats_name]
        match = re.search(stats_regex, ping_output)
        if not match:
            raise ValueError(f'Unable to find {stats_name} in ping output:\n{ping_output}')
        result = match.groups()
        value = result[0]
        return value

    def _create_ssh_manager_and_register_host(self, app_server):
        self.logger.debug(f"{self.name}: creating ssh manager for downlink ping data transfer")
        self.ssh_manager = SshManager()
        self.ssh_manager.register(app_server['address'], app_server['user'], app_server['password'])
        return self.ssh_manager

    def release_data_transfer(self):
        """Release SSH connections, ensure threads are stopped"""
        # TODO: try to move this implementation to .stop() and call it here
        #  (additional behavioural tests and unittests adjustions are needed)
        self.logger.debug(f"{self.name} call: release data transfer")
        if not self.is_running():
            self.logger.debug(f"{self.name}: nothing to release, dt was already finished")
            return
        if self.is_direction_downlink:
            self.ssh_manager.close_all_ssh_connections()
        else:
            self.ue_instance.rpc_client.stop_data_transfer(ue_id=self.ue_instance.ue_id,
                                                           data_transfer_id=self.name)
        self.logger.debug(f"{self.name}: data transfer finished")

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        if self.is_dt_running:
            if self.is_direction_downlink:
                self.is_dt_running = not self.downlink_ssh_reader.is_finish()
            else:
                dt_current_state = self.ue_instance.rpc_client.get_data_transfer_state(
                    ue_id=self.ue_instance.ue_id, data_transfer_id=self.name)
                self.logger.debug(f"{self.name} current state: {dt_current_state}")
                self.is_dt_running = dt_current_state == "started"
        self.logger.debug(f"{self.name} is still running: {self.is_dt_running}")
        return self.is_dt_running

    def get_data_transfer_statistics(self, **kwargs):
        """
        Get ICMP data transfer statistics
        :return: list: packet loss, RTT min, RTT max, RTT avg
        """
        if not self.result:
            raise NotImplementedError("Unable to get statistics before awaiting for finished data transfer.\n"
                                      "Please use Await Data Transfer Finish keyword first.")
        return {stat: self._husk_value_from_ping_output(stat, self.result)
                for stat in ping_options.PING_STATS_REGEX.keys()}

    def stop(self):
        """
        Stop ICMP data transfer by killing ping command
        :return:
        """
        self.logger.debug(f'{self.name}: stopping data transfer')
        if self.is_direction_downlink:
            self.ssh_manager.send_ctrl_c(self._get_app_server_ip())
            self.result = self.utils.get_non_blocking_reader_result(self.downlink_ssh_reader,
                                                                    timeout=int(self.dt_config['timeout']),
                                                                    interval=self.dt_config['interval'])
        else:
            self.ue_instance.rpc_client.stop_data_transfer(ue_id=self.ue_instance.ue_id,
                                                           data_transfer_id=self.name)
            self.result = self.ue_instance.rpc_client.get_data_transfer_output(ue_id=self.ue_instance.ue_id,
                                                                               data_transfer_id=self.name,
                                                                               raw_output=True)['raw_output']
        self.result = "\n".join(self.result)
        self._verify_ping_output(self.result, self.dt_config['allowed_packet_loss'])
        if not self.is_running():
            self.logger.debug(f"{self.name}: nothing to release, dt was already finished")
            return
        else:
            if self.is_direction_downlink:
                self.ssh_manager.close_all_ssh_connections()
            else:
                self.ue_instance.rpc_client.stop_data_transfer(ue_id=self.ue_instance.ue_id,
                                                               data_transfer_id=self.name)
        self.logger.debug(f"{self.name}: data transfer finished")

    def check_data_transfer(self):
        """Not implemented"""
        raise NotImplementedError

    def reset_statistics(self):
        """Not implemented"""
        raise NotImplementedError

    def get_average_throughput(self, **kwargs):
        """Not implemented"""
        raise NotImplementedError

    def get_datagram_loss(self):
        """Not implemented"""
        raise NotImplementedError


class IcmpDtConfigPacker(AndroidUeDtConfigPacker):

    def __init__(self, dt_definition, yaml_config, logger):
        """Object for packing data transfer config into one dict"""
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        super().__init__(dt_definition, yaml_config, logger)

    def _pack_dt_keys(self, configuration):
        dt_allowed_keys = [('address', str, None),
                           ('interval', float, ping_options.DEFAULT_INTERVAL),
                           ('ping_count', int, 10),
                           ('bind_interface_ip', str, None),
                           ('packet_size', int, None),
                           ('interface_name', str, None),
                           ('allowed_packet_loss', int, 0),
                           ('duration', Union[int, None], DT_MAX_TIME if self.dt_definition.is_forever_duration() else None),
                           ('ping_forever', bool, False)]
        dt_section = configuration['data_transfer']['ping']
        for key in dt_allowed_keys:
            self._apply_key(dt_section, *key)
        self._set_ping_duration()
        self._set_ping_timeout()

    @staticmethod
    def _get_app_server_from_yml(yaml_config):
        return yaml_config['data_transfer']['ping']['app_server']

    def _set_ping_timeout(self, overhead=ping_options.DEFAULT_TIMEOUT_OVERHEAD):
        if self.dt_config_to_uepc['duration']:
            self.dt_config_to_uepc['timeout'] = self.dt_config_to_uepc['duration'] + float(overhead)
        else:
            ping_count, interval = self.dt_config_to_uepc['ping_count'], self.dt_config_to_uepc['interval']
            self.dt_config_to_uepc['timeout'] = ping_count * interval + float(overhead)

    def _set_ping_duration(self):
        if not self.dt_definition.is_forever_duration() or self._is_ping_forever() is True:
            # For backward compatibility, we need to support 'ping_forever' parameter
            # By default, if duration is not set, we will use ping_count
            duration = float(self.dt_definition.duration)
            self.logger.debug(f'Setting data transfer duration={duration}, skipping ping_count parameter.')
            self.dt_config_to_uepc['duration'] = int(duration)
            self.dt_config_to_uepc['ping_count'] = None
        else:
            self.dt_config_to_uepc['duration'] = None

    def _is_ping_forever(self):
        try:
            return self.dt_definition.protocol_details['ping_forever']
        except KeyError:
            return False
